@require_GET
@login_required
def obtener_movimientos_producto(request):
    sucursal_id = request.session.get('idSucursalActual')
    if not sucursal_id:
        return JsonResponse({'success': False, 'error': 'No hay sucursal activa'}, status=400)

    from datetime import datetime, timedelta
    from django.utils.dateparse import parse_date
    from django.utils import timezone
    
    def parse_fecha_ddmmyyyy(fecha_str):
        try:
            if fecha_str and '/' in fecha_str:
                return datetime.strptime(fecha_str, '%d/%m/%Y').date()
            elif fecha_str:
                return parse_date(fecha_str)
        except Exception:
            return None
        return None
    
    def limpiar_prefijo(valor):
        """Limpia prefijos de atributos como 'Marca:', 'Color:', 'Género:'"""
        if not valor:
            return ''
        for prefijo in ['Marca:', 'Color:', 'Género:']:
            if valor.startswith(prefijo):
                return valor[len(prefijo):].strip()
        return valor.strip()

    # Filtros
    fecha_inicio = request.GET.get('fecha_inicio')
    fecha_fin = request.GET.get('fecha_fin')
    tipo = request.GET.get('tipo')  # INGRESO, EGRESO, etc.
    articulo = request.GET.get('articulo')
    responsable = request.GET.get('responsable')
    concepto = request.GET.get('concepto')
    page = int(request.GET.get('page', 1))
    page_size = min(int(request.GET.get('page_size', 50)), 100)

    fecha_inicio_dt = parse_fecha_ddmmyyyy(fecha_inicio)
    fecha_fin_dt = parse_fecha_ddmmyyyy(fecha_fin)
    
    # ✅ OPTIMIZACIÓN: Fecha por defecto (últimos 30 días) si no hay filtros de fecha
    # Esto evita cargar todo el historial en la carga inicial
    hoy = timezone.localdate()
    usar_fecha_defecto = not fecha_inicio and not fecha_fin
    if usar_fecha_defecto:
        fecha_inicio_dt = hoy - timedelta(days=30)
        fecha_fin_dt = hoy

    # Mostrar solo movimientos relevantes para esta sucursal:
    # - Egresos donde esta sucursal es el origen (cosas que salieron)
    # - Ingresos donde esta sucursal es el destino (cosas que llegaron)
    # - Movimientos sin sucursal_destino que pertenecen a esta sucursal (ventas, ajustes, etc.)
    movimientos = Movimientos_Producto.objects.select_related(
        'ProductoTalla__producto__atributo1',
        'ProductoTalla__producto__atributo2', 
        'ProductoTalla__producto__atributo3',
        'dte', 
        'ticket', 
        'sucursal_origen', 
        'sucursal_destino'
    ).filter(
        Q(sucursal_origen_id=sucursal_id, tipo_movimiento='EGRESO') |
        Q(sucursal_destino_id=sucursal_id, tipo_movimiento='INGRESO') |
        Q(sucursal_origen_id=sucursal_id, sucursal_destino__isnull=True)
    )
    
    # Aplicar filtro de fecha (incluir movimientos sin fecha para no perder datos)
    if fecha_inicio_dt and fecha_fin_dt:
        movimientos = movimientos.filter(
            Q(fecha__gte=fecha_inicio_dt, fecha__lte=fecha_fin_dt) | Q(fecha__isnull=True)
        )
    elif fecha_inicio_dt:
        movimientos = movimientos.filter(Q(fecha__gte=fecha_inicio_dt) | Q(fecha__isnull=True))
    elif fecha_fin_dt:
        movimientos = movimientos.filter(Q(fecha__lte=fecha_fin_dt) | Q(fecha__isnull=True))
    
    # Aplicar otros filtros
    if tipo:
        movimientos = movimientos.filter(tipo_movimiento__iexact=tipo)
    if articulo:
        movimientos = movimientos.filter(ProductoTalla__producto__articulo__icontains=articulo)
    if responsable:
        movimientos = movimientos.filter(responsable__icontains=responsable)
    if concepto:
        movimientos = movimientos.filter(concepto__icontains=concepto)

    # ✅ OPTIMIZACIÓN: Contar y paginar de forma eficiente
    # Primero ordenamos, luego contamos solo si es necesario para la paginación
    movimientos = movimientos.order_by('-fecha', '-hora')
    total_count = movimientos.count()
    offset = (page - 1) * page_size
    movimientos = movimientos[offset:offset+page_size]

    data = []
    for m in movimientos:
        prod = m.ProductoTalla.producto
        
        # ✅ MEJORA: Construir referencia priorizando referencia_externa para devoluciones
        # Las devoluciones ya guardan el numero_operacion en referencia_externa
        if m.referencia_externa:
            # Si existe referencia_externa, usarla (devoluciones, cambios, etc.)
            referencia = m.referencia_externa
            # Agregar contexto adicional si aplica
            if m.concepto in ('DEVOLUCION_CLIENTE', 'DEVOLUCION_PROVEEDOR') and m.ticket:
                referencia = f"{m.referencia_externa} (Ticket #{m.ticket.correlativo})"
        elif m.tipo_movimiento == 'TRASPASO' and m.sucursal_destino:
            referencia = f"Destino: {m.sucursal_destino.alias}"
        elif m.dte:
            referencia = f"{m.dte.tipo_documento} #{m.dte.numero_documento}"
        elif m.ticket:
            referencia = f"Ticket #{m.ticket.correlativo}"
        else:
            referencia = ''
        
        # Extraer atributos del producto (ya cargados por select_related)
        marca = limpiar_prefijo(prod.atributo1.valor if prod.atributo1 else '')
        color = limpiar_prefijo(prod.atributo2.valor if prod.atributo2 else '')
        genero = limpiar_prefijo(prod.atributo3.valor if prod.atributo3 else '')
        
        data.append({
            'id': m.id,
            'fecha': m.fecha.strftime('%Y-%m-%d'),
            'hora': m.hora.strftime('%H:%M:%S') if m.hora else '',
            'articulo': prod.articulo,
            'descripcion': prod.descripcion,
            'marca': marca,
            'color': color,
            'genero': genero,
            'talla': m.ProductoTalla.talla,
            'sku': m.ProductoTalla.sku,
            'cantidad': m.cantidad,
            'costo': m.costo,
            'precio': m.precio,
            'sobreprecio': m.sobreprecio,
            'tipo_movimiento': m.tipo_movimiento,
            'concepto': m.concepto,
            'responsable': m.responsable,
            'dte': m.dte.numero_documento if m.dte else None,
            'referencia_externa': referencia,
            'sucursal_destino': m.sucursal_destino.alias if m.sucursal_destino else '',
        })
    
    return JsonResponse({
        'success': True,
        'items': data,
        'pagination': {
            'page': page,
            'page_size': page_size,
            'total_count': total_count,
            'total_pages': (total_count + page_size - 1) // page_size,
            'has_next': page * page_size < total_count,
            'has_previous': page > 1
        },
        # ✅ OPTIMIZACIÓN: Informar al frontend si se usaron fechas por defecto
        'filtros_aplicados': {
            'fecha_inicio': fecha_inicio_dt.strftime('%d/%m/%Y') if fecha_inicio_dt else None,
            'fecha_fin': fecha_fin_dt.strftime('%d/%m/%Y') if fecha_fin_dt else None,
            'fecha_defecto_aplicada': usar_fecha_defecto
        }
    })

@require_GET
@login_required
def obtener_productos(request):
    q = request.GET.get('q', '').strip()
    page = int(request.GET.get('page', 1))
    page_size = min(int(request.GET.get('page_size', 20)), 100)
    # Allow explicit sucursal_id override; 'todas' means skip filter
    sucursal_id_param = request.GET.get('sucursal_id', '')
    if sucursal_id_param == 'todas':
        sucursal_id = None
    elif sucursal_id_param:
        sucursal_id = sucursal_id_param
    else:
        sucursal_id = request.session.get('idSucursalActual')
    productos = Producto_Talla.objects.select_related('producto')
    if sucursal_id:
        productos = productos.filter(producto__sucursal_id=sucursal_id)
    if q:
        productos = productos.filter(
            Q(producto__articulo__icontains=q) |
            Q(producto__descripcion__icontains=q) |
            Q(producto__atributo1__valor__icontains=q) |
            Q(producto__atributo2__valor__icontains=q) |
            Q(producto__atributo3__valor__icontains=q) |
            Q(sku__icontains=q)
        )
    total_count = productos.count()
    offset = (page - 1) * page_size
    productos = productos.order_by('producto__articulo', 'talla')[offset:offset+page_size]
    def limpiar_prefijo(valor):
        if not valor:
            return ''
        for prefijo in ['Marca:', 'Color:', 'Género:']:
            if valor.startswith(prefijo):
                return valor[len(prefijo):].strip()
        return valor.strip()
    results = []
    for pt in productos:
        prod = pt.producto
        marca = limpiar_prefijo(prod.atributo1.valor if prod.atributo1 else '')
        color = limpiar_prefijo(prod.atributo2.valor if prod.atributo2 else '')
        genero = limpiar_prefijo(prod.atributo3.valor if prod.atributo3 else '')
        
        # Calcular stock según sistema híbrido
        stock = pt.stock_total() if hasattr(pt, 'stock_total') else pt.stock
        
        text = f"{prod.articulo} - {prod.descripcion} | Marca: {marca} | Color: {color} | Género: {genero} | Talla: {pt.talla} | SKU: {pt.sku}"
        results.append({
            'id': pt.id,
            'text': text,
            'sku': pt.sku,
            'marca': marca,
            'color': color,
            'genero': genero,
            'talla': pt.talla,
            'stock': stock,
            'costo': prod.costo,
            'sobreprecio': prod.sobreprecio,
            'precioventa': prod.precioventa,
            'producto_id': prod.id,
            'sucursal_id': prod.sucursal_id,
            'sucursal_nombre': prod.sucursal.alias if prod.sucursal else '',
            'excluir_de_analitica': prod.excluir_de_analitica,
        })
    return JsonResponse({
        'results': results,
        'pagination': {'more': offset + page_size < total_count}
    })

@require_GET
@login_required
def reporte_despachos_por_proveedor(request):
    """
    Reporte que muestra por cada proveedor y DTE:
    - Total de productos ingresados
    - Total de productos despachados (vendidos, transferidos, etc.)
    - Saldo restante
    - Resumen global de KPIs
    
    NOTA: En una COMPRA, el EMISOR es el proveedor (quien nos vende/factura)
    """
    # Filtros
    proveedor_id = request.GET.get('proveedor_id')
    fecha_inicio = request.GET.get('fecha_inicio')
    fecha_fin = request.GET.get('fecha_fin')
    dte_numero = request.GET.get('dte_numero')
    # Por defecto se excluye la facturación interna (emisor == receptor).
    # El frontend puede pasar excluir_interna=false para incluirlas.
    excluir_interna = request.GET.get('excluir_interna', 'true').lower() != 'false'
    
    # Parámetros de paginación
    page = int(request.GET.get('page', 1))
    page_size = min(int(request.GET.get('page_size', 25)), 100)
    
    # Tipos de documento válidos para compras a proveedores
    # Excluimos boletas (son de venta al público) y tickets
    TIPOS_DOCUMENTO_EXCLUIDOS = [
        'BOLETA ELECTRONICA',
        'BOLETA PAPEL',
        'TICKET',
    ]
    
    # Query base: DTEs con tipo_transaccion='COMPRA'
    # En una compra según crearDteCompras:
    #   - emisor = proveedor (quien nos vende/emite la factura)
    #   - receptor = nosotros (quien compra/recibe la factura)
    dtes_query = Dte.objects.filter(
        tipo_transaccion='COMPRA'
    ).exclude(
        tipo_documento__in=TIPOS_DOCUMENTO_EXCLUIDOS
    ).select_related('emisor', 'receptor')

    # Excluir facturación interna: DTEs donde el emisor y receptor son la misma empresa.
    # Estos son auto-facturaciones que distorsionan los KPIs de compras a proveedores.
    if excluir_interna:
        dtes_query = dtes_query.exclude(emisor_id=F('receptor_id'))

    # Aplicar filtros - Buscar por emisor (que es el proveedor en compras)
    if proveedor_id:
        dtes_query = dtes_query.filter(emisor_id=proveedor_id)
    if fecha_inicio:
        dtes_query = dtes_query.filter(fecha_emision__gte=fecha_inicio)
    if fecha_fin:
        dtes_query = dtes_query.filter(fecha_emision__lte=fecha_fin)
    if dte_numero:
        dtes_query = dtes_query.filter(numero_documento__icontains=dte_numero)
    
    # Contar total para paginación
    total_count = dtes_query.count()
    total_pages = (total_count + page_size - 1) // page_size
    
    # ========== RESUMEN GLOBAL (todos los registros filtrados) ==========
    resumen_global = {
        'total_proveedores': dtes_query.values('emisor_id').distinct().count(),
        'total_dtes': total_count,
        'dtes_pagados': dtes_query.filter(estado_pago='PAGADO').count(),
        'dtes_pendientes': dtes_query.filter(estado_pago='PENDIENTE').count(),
        'dtes_aceptados': dtes_query.filter(estado_dte='ACEPTADO').count(),
        'total_unidades_ingresadas': 0,
        'total_unidades_despachadas': 0,
        'total_monto_compras': 0,
        'monto_minimo': 0,
        'monto_maximo': 0,
    }
    
    # Calcular métricas globales de movimientos para todos los DTEs filtrados
    all_dtes_ids = list(dtes_query.values_list('id', flat=True))
    if all_dtes_ids:
        # Ingresos globales
        ingresos_globales = Movimientos_Producto.objects.filter(
            dte_id__in=all_dtes_ids,
            tipo_movimiento='INGRESO'
        ).aggregate(
            total_cantidad=Sum('cantidad'),
            total_costo=Sum(F('cantidad') * F('costo'))
        )
        
        # Egresos globales
        egresos_globales = Movimientos_Producto.objects.filter(
            dte_id__in=all_dtes_ids,
            tipo_movimiento='EGRESO'
        ).aggregate(
            total_cantidad=Sum('cantidad'),
            total_costo=Sum(F('cantidad') * F('costo'))
        )
        
        resumen_global['total_unidades_ingresadas'] = ingresos_globales['total_cantidad'] or 0
        resumen_global['total_unidades_despachadas'] = abs(egresos_globales['total_cantidad'] or 0)
        resumen_global['total_monto_compras'] = float(ingresos_globales['total_costo'] or 0)

        # Unidades totales comprometidas en DTEs y pendientes de ingreso
        total_en_dtes = Dte_Productos.objects.filter(dte_id__in=all_dtes_ids).aggregate(t=Sum('stock'))['t'] or 0
        resumen_global['total_unidades_en_dtes'] = total_en_dtes
        resumen_global['total_unidades_pendientes'] = max(0, total_en_dtes - resumen_global['total_unidades_ingresadas'])

        # Calcular monto mínimo y máximo
        montos_dtes = dtes_query.aggregate(
            monto_min=Min('monto_con_iva'),
            monto_max=Max('monto_con_iva'),
            monto_promedio=Avg('monto_con_iva')
        )
        resumen_global['monto_minimo'] = float(montos_dtes['monto_min'] or 0)
        resumen_global['monto_maximo'] = float(montos_dtes['monto_max'] or 0)
        resumen_global['monto_promedio'] = float(montos_dtes['monto_promedio'] or 0)
    
    # Aplicar paginación para datos de tabla
    offset = (page - 1) * page_size
    dtes = dtes_query.order_by('-fecha_emision')[offset:offset + page_size]
    
    resultado = []
    
    for dte in dtes:
        # Calcular ingresos (movimientos de INGRESO asociados a este DTE)
        ingresos = Movimientos_Producto.objects.filter(
            dte=dte,
            tipo_movimiento='INGRESO'
        ).aggregate(
            total_cantidad=Sum('cantidad'),
            total_costo=Sum(F('cantidad') * F('costo'))
        )
        
        # Calcular despachos (movimientos de EGRESO asociados a este DTE)
        despachos = Movimientos_Producto.objects.filter(
            dte=dte,
            tipo_movimiento='EGRESO'
        ).aggregate(
            total_cantidad=Sum('cantidad'),
            total_costo=Sum(F('cantidad') * F('costo'))
        )
        
        # Valores por defecto
        total_ingresado = ingresos['total_cantidad'] or 0
        total_despachado = abs(despachos['total_cantidad'] or 0)  # Valor absoluto porque egresos son negativos
        saldo_restante = total_ingresado - total_despachado

        # Unidades comprometidas en el DTE y pendientes de ingreso
        unidades_en_dte = Dte_Productos.objects.filter(dte=dte).aggregate(t=Sum('stock'))['t'] or 0
        unidades_pendientes_ingreso = max(0, unidades_en_dte - total_ingresado)

        # Calcular montos
        monto_ingresado = ingresos['total_costo'] or 0
        monto_despachado = abs(despachos['total_costo'] or 0)
        monto_restante = monto_ingresado - monto_despachado
        
        resultado.append({
            'dte_id': dte.id,
            'dte_numero': dte.numero_documento,
            'dte_tipo': dte.tipo_documento,
            'fecha_emision': dte.fecha_emision.strftime('%Y-%m-%d'),
            'proveedor_id': dte.emisor.id if dte.emisor else None,
            'proveedor_nombre': dte.emisor.nombre if dte.emisor else 'Sin proveedor',
            'proveedor_rut': dte.emisor.rut if dte.emisor else '-',
            'unidades_en_dte': unidades_en_dte,
            'unidades_pendientes_ingreso': unidades_pendientes_ingreso,
            'total_ingresado': total_ingresado,
            'total_despachado': total_despachado,
            'saldo_restante': saldo_restante,
            'monto_ingresado': float(monto_ingresado),
            'monto_despachado': float(monto_despachado),
            'monto_restante': float(monto_restante),
            'estado_dte': dte.estado_dte,
            'estado_pago': dte.estado_pago
        })
    
    return JsonResponse({
        'success': True,
        'data': resultado,
        'resumen': resumen_global,
        'excluir_interna': excluir_interna,
        'pagination': {
            'current_page': page,
            'total_pages': total_pages,
            'total_records': total_count,
            'page_size': page_size
        }
    })

